import type { JSX } from "react"

// Vine unit: 1367 × 1920 SVG user units (potrace 0.1 scale, y-flipped)
const UNIT_WIDTH = 1367
const UNIT_HEIGHT = 1920

// 30 repeats × 1920 SVG units = 57,600 total SVG height.
// At w-[280px] rendered width → ~11,787px tall on mobile.
// Increase REPEAT_COUNT if final page height exceeds ~12,000px.
const REPEAT_COUNT = 30

// 3-step opacity cycle × 2-step mirror cycle = 6-unit visual period (~2,360px on mobile).
// Prevents the repeated bouquet composition from reading as an obvious tile.
const OPACITY_CYCLE = [0.05, 0.08, 0.065] as const

const VINE_REPEATS = Array.from({ length: REPEAT_COUNT }, (_, i) => ({
  key: i,
  opacity: OPACITY_CYCLE[i % 3] ?? 0.06,
  transform:
    i % 2 === 0
      ? `translate(0,${i * UNIT_HEIGHT})`
      : `translate(${UNIT_WIDTH},${i * UNIT_HEIGHT}) scale(-1,1)`,
}))

